{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Apixaban, a highly transferable analogue, has absolute oral bioavailability of 51% in humans after a 2.5 mg oral dose, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Papaverine, despite extensive first-pass metabolism, showed absolute bioavailability of 22% from a sustained-release product in humans, still meeting the F>=20% threshold and representing the lowest retrieved value.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Alpelisib has oral bioavailability of about 68.7% in healthy subjects at 300 mg with negligible first-pass metabolism, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Brepocitinib absolute bioavailability was estimated at 75% in humans based on a mass balance study, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Vernakalant in fasted healthy volunteers had absolute bioavailability of 71 ± 21% after oral dosing, directly matching the fasted condition and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Selpercatinib mean absolute bioavailability was 73% from capsules in volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Daridorexant absolute bioavailability was 62% based on an oral dose with IV microdose, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "AZD0837 absolute bioavailability was 22–55% in healthy volunteers, with the lower bound at the threshold and central values above it, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved analogues with very high assay-transfer scores show absolute oral bioavailability at or above 22%, with most values between 50% and 75%, strongly supporting F>=20% for the query molecule.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule itself.",
    "No retrieved analogue with F<20% was available to anchor the low-bioavailability side.",
    "Some records are not explicitly absolute bioavailability or do not specify fasted conditions, though the fasted studies retrieved still support high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

